<template><view class="page"><input v-model="keyword" class="search" placeholder="搜索司机姓名或手机号" @confirm="refresh"/><view v-for="item in list" :key="item.id" class="card"><view><text class="name">{{item.name||'未命名司机'}}</text><text class="mobile">{{item.mobile||'-'}}</text></view><text :class="['status','s'+item.onlineStatus]">{{online(item.onlineStatus)}}</text><text class="vehicle">{{item.plateNumber||'未填车牌'}} · {{item.vehicleType||'未填车型'}}</text></view><view v-if="!loading&&!list.length" class="empty">暂无司机</view><button v-if="list.length<total" @click="more">加载更多</button></view></template>
<script>import{api}from'@/api/index.js';export default{data(){return{keyword:'',list:[],page:1,total:0,loading:false}},onShow(){this.refresh()},methods:{refresh(){this.page=1;this.list=[];this.load()},async load(){this.loading=true;try{const r=await api.getDrivers({page:this.page,limit:20,keyword:this.keyword});this.total=r.data.total||0;this.list=this.list.concat(r.data.records||[])}catch(e){console.error(e)}finally{this.loading=false}},more(){this.page++;this.load()},online(s){return['离线','在线','运输中'][s]||'离线'}}}</script>
<style scoped>.page{min-height:100vh;padding:20rpx;background:#f5f5f5}.search{padding:22rpx 26rpx;margin-bottom:20rpx;background:#fff;border-radius:12rpx}.card{position:relative;padding:26rpx;margin-bottom:16rpx;background:#fff;border-radius:12rpx}.name{font-size:30rpx;font-weight:600}.mobile{margin-left:20rpx;color:#999;font-size:24rpx}.vehicle{display:block;margin-top:18rpx;color:#666;font-size:25rpx}.status{position:absolute;right:24rpx;top:24rpx;color:#999}.s1{color:#52c41a}.s2{color:#fa8c16}.empty{padding:100rpx;text-align:center;color:#999}</style>
